import Foundation

/// The keyset compiled into the binary (generated by plugin/scripts/sync-builtin-rules.sh from keys/keyset.json and
/// its signature). Empty until the maintainer has signed a keyset; with none known, nothing is trusted.
public enum BuiltinKeyset {
    public static var bundled: (json: Data, signature: String)? {
        let sig = BuiltinKeysetData.signature.trimmingCharacters(in: .whitespacesAndNewlines)
        // Base64, not a string literal: the signature covers the exact bytes, trailing newline included.
        guard let json = Data(base64Encoded: BuiltinKeysetData.jsonBase64), !json.isEmpty, !sig.isEmpty else { return nil }
        return (json, sig)
    }
}

/// `<CBB_HOME>/keys/current/keyset.json(.sig)`: the refreshed keyset, next to the compiled-in one.
public enum KeysetStore {
    static func cache(_ home: URL) -> PairCache { PairCache(root: home.appendingPathComponent("keys"), fileName: "keyset.json") }

    public static func cachePaths(home: URL) -> (json: URL, sig: URL) { cache(home).currentPaths }

    /// The keyset to go by: the verified one (valid OR expired) with the newest `issued_at` among the cached copy and the bundled one
    /// (a cached copy wins a tie). That `issued_at` is a floor: an older keyset never wins, however valid it still is. When the
    /// newest one has expired the state is `expired` (fail closed), not the older valid copy. With nothing verified: `invalid`
    /// when something exists, else `absent`.
    public static func load(home: URL, rootKey: Data, bundled: (json: Data, signature: String)?, now: Date = Date()) -> KeysetState {
        var found: [KeysetState] = []
        if let c = cache(home).read() {
            found.append(tag(KeysetVerifier.verify(json: c.json, signatureBase64: c.sig, rootKey: rootKey, now: now), "cache"))
        }
        if let b = bundled {
            found.append(tag(KeysetVerifier.verify(json: b.json, signatureBase64: b.signature, rootKey: rootKey, now: now), "bundled"))
        }
        func keyset(_ s: KeysetState) -> Keyset? {
            switch s {
            case .valid(let k, _), .expired(let k): return k
            default: return nil
            }
        }
        var best: KeysetState?
        for s in found {
            guard let k = keyset(s) else { continue }
            if let b = best, let bk = keyset(b), k.issuedAt <= bk.issuedAt { continue }
            best = s
        }
        return best ?? found.first ?? .absent
    }

    public static func writeCache(json: Data, signature: String, home: URL) throws {
        try cache(home).write(json: json, signature: signature)
    }

    private static func tag(_ s: KeysetState, _ source: String) -> KeysetState {
        if case .valid(let k, _) = s { return .valid(k, source: source) }
        return s
    }
}
